## My answer to the user prompt

A simple MVVM implementation can use `AVAudioRecorder` for recording and its metering API to drive an equalizer-style view. Add `NSMicrophoneUsageDescription` to the app’s `Info.plist` with a message explaining why the app needs microphone access.

```swift
import AVFoundation
import SwiftUI

@MainActor
final class VoiceRecorderViewModel: ObservableObject {
    @Published private(set) var isRecording = false
    @Published private(set) var audioLevel: CGFloat = 0
    @Published private(set) var savedURL: URL?
    @Published var errorMessage: String?

    private var recorder: AVAudioRecorder?
    private var meterTimer: Timer?

    func startRecording() {
        guard !isRecording else { return }

        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            Task { @MainActor in
                guard let self else { return }
                guard granted else {
                    self.errorMessage = "Microphone access is required to record."
                    return
                }
                self.beginRecording()
            }
        }
    }

    private func beginRecording() {
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
            try session.setActive(true)

            let folder = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            let url = folder.appendingPathComponent("Recording-\(UUID().uuidString).m4a")
            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(url: url, settings: settings)
            newRecorder.isMeteringEnabled = true
            guard newRecorder.record() else {
                throw NSError(domain: "VoiceRecorder", code: 1,
                              userInfo: [NSLocalizedDescriptionKey: "Could not start recording."])
            }

            recorder = newRecorder
            savedURL = nil
            isRecording = true

            meterTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) { [weak self] _ in
                Task { @MainActor in self?.updateMeter() }
            }
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private func updateMeter() {
        recorder?.updateMeters()
        let db = recorder?.averagePower(forChannel: 0) ?? -60
        audioLevel = CGFloat(max(0, min(1, (db + 60) / 60)))
    }

    func stopRecording() {
        guard isRecording else { return }

        recorder?.stop()
        savedURL = recorder?.url
        recorder = nil
        meterTimer?.invalidate()
        meterTimer = nil
        audioLevel = 0
        isRecording = false

        do {
            try AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}

struct VoiceRecorderView: View {
    @StateObject private var model = VoiceRecorderViewModel()

    var body: some View {
        VStack(spacing: 32) {
            Text("Voice Recorder").font(.title)

            HStack(alignment: .center, spacing: 6) {
                ForEach(0..<7, id: \.self) { index in
